                 //                     "slLimitPrice": null
                 //                 },
                 //             ],
                 //             "cursor": "1322441328637100035"
                 //         }
                 //     }
                 //
                 // uta trigger
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1753058447920,
                 //         "data": {
                 //             "list": [
                 //                 {
                 //                     "orderId": "1330984742276198400",
                 //                     "clientOid": "1330984742276198400",
                 //                     "symbol": "BTCUSDT",
                 //                     "category": "USDT-FUTURES",
