  /**
   * @method
   * @name bitget#fetchLedger
   * @description fetch the history of changes, actions done by the user or
   * operations that altered the balance of the user
   * @see https://www.bitget.com/api-doc/spot/account/Get-Account-Bills
   * @see https://www.bitget.com/api-doc/contract/account/Get-Account-Bill
   * @param {string} [code] unified currency code, default is undefined
   * @param {int} [since] timestamp in ms of the earliest ledger entry, default
   * is undefined
   * @param {int} [limit] max number of ledger entries to return, default is
   * undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] end time in ms
   * @param {string} [params.symbol] *contract only* unified market symbol
   * @param {string} [params.productType] *contract only* 'USDT-FUTURES',
   * 'USDC-FUTURES', 'COIN-FUTURES', 'SUSDT-FUTURES', 'SUSDC-FUTURES' or
   * 'SCOIN-FUTURES'
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object} a [ledger structure]{@link
   * https://docs.ccxt.com/?id=ledger-entry-structure}
   */
  std::shared_future<std::any>
  fetchLedger(std::any code = std::any{}, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any symbol =
                     this->safeString(params, std::string("symbol"));
                 params = this->omit(params, std::string("symbol"));
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any marketType = std::any{};
                 std::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(std::string("fetchLedger"),
                                                     market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchLedger"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   std::any cursorReceived = std::any{};
                   if (isTrue(!isEqual(marketType, std::string("spot")))) {
                     cursorReceived = std::string("endId");
                   }
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchLedger"), symbol, since, limit, params,
                       cursorReceived, std::string("idLessThan")));
                 }
                 std::any currency = std::any{};
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(code, std::any{}))) {
                   currency = this->currency(code);
                   ::setValue(request, std::string("coin"),
                              ::getValue(currency, std::string("id")));
                 }
                 std::any requestparamsVariable = this->handleUntilOption(
                     std::string("endTime"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response = awaitValue(this->privateSpotGetV2SpotAccountBills(
                       this->extend(request, params)));
                 } else {
                   if (isTrue(!isEqual(symbol, std::any{}))) {
                     ::setValue(request, std::string("symbol"),
                                this->safeString(market, std::string("id")));
                   }
                   std::any productType = std::any{};
                   std::any productTypeparamsVariable =
                       this->handleProductTypeAndParams(market, params);
                   productType = ::getValue(productTypeparamsVariable, 0);
                   params = ::getValue(productTypeparamsVariable, 1);
                   ::setValue(request, std::string("productType"), productType);
                   response = awaitValue(this->privateMixGetV2MixAccountBill(
                       this->extend(request, params)));
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700795836415,
                 //         "data": [
                 //             {
                 //                 "billId": "1111506298997215233",
                 //                 "coin": "USDT",
                 //                 "groupType": "transfer",
                 //                 "businessType": "transfer_out",
                 //                 "size": "-11.64958799",
                 //                 "balance": "0.00000000",
                 //                 "fees": "0.00000000",
                 //                 "cTime": "1700729673028"
                 //             },
                 //         ]
                 //     }
                 //
                 // swap and future
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700795977890,
                 //         "data": {
                 //             "bills": [
                 //                 {
                 //                     "billId": "1111499428100472833",
                 //                     "symbol": "",
                 //                     "amount": "-11.64958799",
                 //                     "fee": "0",
                 //                     "feeByCoupon": "",
                 //                     "businessType": "trans_to_exchange",
                 //                     "coin": "USDT",
                 //                     "cTime": "1700728034996"
                 //                 },
                 //             ],
                 //             "endId": "1098396773329305606"
                 //         }
                 //     }
                 //
                 std::any data = this->safeValue(response, std::string("data"));
                 if (isTrue(
                         isTrue((isEqual(marketType, std::string("swap")))) ||
                         isTrue(
                             (isEqual(marketType, std::string("future")))))) {
                   std::any bills = this->safeValue(data, std::string("bills"),
                                                    ccxt::list{});
                   return this->parseLedger(bills, currency, since, limit);
                 }
                 return this->parseLedger(data, currency, since, limit);
               })
        .share();
  }

  std::any parseLedgerEntry(std::any item,
                            std::any currency = std::any{}) override {
    //
    // spot
    //
    //     {
    //         "billId": "1111506298997215233",
    //         "coin": "USDT",
    //         "groupType": "transfer",
    //         "businessType": "transfer_out",
    //         "size": "-11.64958799",
    //         "balance": "0.00000000",
    //         "fees": "0.00000000",
    //         "cTime": "1700729673028"
    //     }
    //
    // swap and future
    //
    //     {
    //         "billId": "1111499428100472833",
    //         "symbol": "",
    //         "amount": "-11.64958799",
    //         "fee": "0",
    //         "feeByCoupon": "",
    //         "businessType": "trans_to_exchange",
    //         "coin": "USDT",
    //         "cTime": "1700728034996"
    //     }
    //
    std::any currencyId = this->safeString(item, std::string("coin"));
    std::any code = this->safeCurrencyCode(currencyId, currency);
    currency = this->safeCurrency(currencyId, currency);
    std::any timestamp = this->safeInteger(item, std::string("cTime"));
    std::any after = this->safeNumber(item, std::string("balance"));
    std::any fee =
        this->safeNumber2(item, std::string("fees"), std::string("fee"));
    std::any amountRaw = this->safeString2(
        item, std::string("size"), std::string("amount"), std::string(""));
    std::any amount = this->parseNumber(ccxt::Precise::stringAbs(amountRaw));
    std::any direction = std::string("in");
    if (isTrue(
            isGreaterThanOrEqual(getIndexOf(amountRaw, std::string("-")), 0))) {
      direction = std::string("out");
    }
    return this->safeLedgerEntry(
        ccxt::dict{
            {std::string("info"), item},
            {std::string("id"), this->safeString(item, std::string("billId"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("direction"), direction},
            {std::string("account"), std::any{}},
            {std::string("referenceId"), std::any{}},
            {std::string("referenceAccount"), std::any{}},
            {std::string("type"), this->parseLedgerType(this->safeString(
                                      item, std::string("businessType")))},
            {std::string("currency"), code},
            {std::string("amount"), amount},
            {std::string("before"), std::any{}},
            {std::string("after"), after},
            {std::string("status"), std::any{}},
            {std::string("fee"),
             ccxt::dict{
                 {std::string("currency"), code},
                 {std::string("cost"), fee},
             }},
        },
        currency);
  }

  virtual std::any parseLedgerType(std::any type) {
    std::any types = ccxt::dict{
        {std::string("trans_to_cross"), std::string("transfer")},
        {std::string("trans_from_cross"), std::string("transfer")},
        {std::string("trans_to_exchange"), std::string("transfer")},
        {std::string("trans_from_exchange"), std::string("transfer")},
        {std::string("trans_to_isolated"), std::string("transfer")},
        {std::string("trans_from_isolated"), std::string("transfer")},
        {std::string("trans_to_contract"), std::string("transfer")},
        {std::string("trans_from_contract"), std::string("transfer")},
        {std::string("trans_to_otc"), std::string("transfer")},
        {std::string("trans_from_otc"), std::string("transfer")},
        {std::string("open_long"), std::string("trade")},
        {std::string("close_long"), std::string("trade")},
        {std::string("open_short"), std::string("trade")},
        {std::string("close_short"), std::string("trade")},
        {std::string("force_close_long"), std::string("trade")},
        {std::string("force_close_short"), std::string("trade")},
        {std::string("burst_long_loss_query"), std::string("trade")},
        {std::string("burst_short_loss_query"), std::string("trade")},
        {std::string("force_buy"), std::string("trade")},
        {std::string("force_sell"), std::string("trade")},
        {std::string("burst_buy"), std::string("trade")},
        {std::string("burst_sell"), std::string("trade")},
        {std::string("delivery_long"), std::string("settlement")},
        {std::string("delivery_short"), std::string("settlement")},
        {std::string("contract_settle_fee"), std::string("fee")},
        {std::string("append_margin"), std::string("transaction")},
        {std::string("adjust_down_lever_append_margin"),
         std::string("transaction")},
        {std::string("reduce_margin"), std::string("transaction")},
        {std::string("auto_append_margin"), std::string("transaction")},
        {std::string("cash_gift_issue"), std::string("cashback")},
        {std::string("cash_gift_recycle"), std::string("cashback")},
        {std::string("bonus_issue"), std::string("rebate")},
        {std::string("bonus_recycle"), std::string("rebate")},
        {std::string("bonus_expired"), std::string("rebate")},
        {std::string("transfer_in"), std::string("transfer")},
        {std::string("transfer_out"), std::string("transfer")},
        {std::string("deposit"), std::string("deposit")},
        {std::string("withdraw"), std::string("withdrawal")},
        {std::string("buy"), std::string("trade")},
        {std::string("sell"), std::string("trade")},
    };
    return this->safeString(types, type, type);
  }

  /**
   * @method
   * @name bitget#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://www.bitget.com/api-doc/spot/trade/Get-Fills
   * @see https://www.bitget.com/api-doc/contract/trade/Get-Order-Fills
   * @see
   * https://www.bitget.com/api-doc/margin/cross/trade/Get-Cross-Order-Fills
   * @see
   * https://www.bitget.com/api-doc/margin/isolated/trade/Get-Isolated-Transaction-Details
   * @see https://www.bitget.com/api-doc/uta/trade/Get-Order-Fills
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch trades for
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any uta = std::any{};
                 std::any utaparamsVariable =
                     awaitValue(this->handleUTAAndParams(
                         params, std::string("fetchMyTrades"), false));
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(isTrue((!isEqual(uta, true))) &&
                            isTrue((isEqual(symbol, std::any{}))))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchMyTrades() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{};
                 std::any requestparamsVariable = this->handleUntilOption(
                     std::string("endTime"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any paginate = false;
                 std::any marginMode = std::any{};
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMyTrades"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 std::any marginModeparamsVariable =
                     this->handleMarginModeAndParams(
                         std::string("fetchMyTrades"), params);
                 marginMode = ::getValue(marginModeparamsVariable, 0);
                 params = ::getValue(marginModeparamsVariable, 1);
                 if (isTrue(paginate)) {
                   std::any cursorReceived = std::any{};
                   std::any cursorSent = std::any{};
                   if (isTrue(isEqual(uta, true))) {
                     cursorReceived = std::string("cursor");
                     cursorSent = std::string("cursor");
                   } else if (isTrue(isEqual(
                                  ::getValue(market, std::string("spot")),
                                  true))) {
                     if (isTrue(!isEqual(marginMode, std::any{}))) {
                       cursorReceived = std::string("minId");
                       cursorSent = std::string("idLessThan");
                     }
                   } else {
                     cursorReceived = std::string("endId");
                     cursorSent = std::string("idLessThan");
                   }
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchMyTrades"), symbol, since, limit,
                       params, cursorReceived, cursorSent));
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(uta, true))) {
                   response = awaitValue(this->privateUtaGetV3TradeFills(
                       this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                      true))) {
                     if (isTrue(!isEqual(marginMode, std::any{}))) {
                       if (isTrue(isEqual(since, std::any{}))) {
                         ::setValue(request, std::string("startTime"),
                                    subtract(this->milliseconds(), 7776000000));
                       }
                       if (isTrue(
                               isEqual(marginMode, std::string("isolated")))) {
                         response = awaitValue(
                             this->privateMarginGetV2MarginIsolatedFills(
                                 this->extend(request, params)));
                       } else if (isTrue(isEqual(marginMode,
                                                 std::string("cross")))) {
                         response = awaitValue(
                             this->privateMarginGetV2MarginCrossedFills(
                                 this->extend(request, params)));
                       }
                     } else {
                       response =
                           awaitValue(this->privateSpotGetV2SpotTradeFills(
                               this->extend(request, params)));
                     }
                   } else {
                     std::any productType = std::any{};
                     std::any productTypeparamsVariable =
                         this->handleProductTypeAndParams(market, params);
                     productType = ::getValue(productTypeparamsVariable, 0);
                     params = ::getValue(productTypeparamsVariable, 1);
                     ::setValue(request, std::string("productType"),
                                productType);
                     response = awaitValue(this->privateMixGetV2MixOrderFills(
                         this->extend(request, params)));
                   }
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700802995406,
                 //         "data": [
                 //             {
                 //                 "userId": "7264631751",
                 //                 "symbol": "BTCUSDT",
                 //                 "orderId": "1098394344925597696",
                 //                 "tradeId": "1098394344974925824",
                 //                 "orderType": "market",
                 //                 "side": "sell",
                 //                 "priceAvg": "28467.68",
                 //                 "size": "0.0002",
                 //                 "amount": "5.693536",
                 //                 "feeDetail": {
                 //                     "deduction": "no",
                 //                     "feeCoin": "USDT",
                 //                     "totalDeductionFee": "",
                 //                     "totalFee": "-0.005693536"
                 //                 },
                 //                 "tradeScope": "taker",
                 //                 "cTime": "1697603539699",
                 //                 "uTime": "1697603539754"
                 //             }
                 //         ]
                 //     }
                 //
                 // spot margin
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700803176399,
                 //         "data": {
                 //             "fills": [
                 //                 {
                 //                     "orderId": "1099353730455318528",
                 //                     "tradeId": "1099353730627092481",
                 //                     "orderType": "market",
                 //                     "side": "sell",
                 //                     "priceAvg": "29543.7",
                 //                     "size": "0.0001",
                 //                     "amount": "2.95437",
                 //                     "tradeScope": "taker",
                 //                     "feeDetail": {
                 //                         "deduction": "no",
                 //                         "feeCoin": "USDT",
                 //                         "totalDeductionFee": "0",
                 //                         "totalFee": "-0.00295437"
                 //                     },
                 //                     "cTime": "1697832275063",
                 //                     "uTime": "1697832275150"
                 //                 },
                 //             ],
                 //             "minId": "1099353591699161118",
                 //             "maxId": "1099353730627092481"
                 //         }
                 //     }
                 //
                 // swap and future
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700803357487,
                 //         "data": {
                 //             "fillList": [
                 //                 {
                 //                     "tradeId": "1111468664328269825",
                 //                     "symbol": "BTCUSDT",
                 //                     "orderId": "1111468664264753162",
                 //                     "price": "37271.4",
                 //                     "baseVolume": "0.001",
                 //                     "feeDetail": [
                 //                         {
                 //                             "deduction": "no",
                 //                             "feeCoin": "USDT",
                 //                             "totalDeductionFee": null,
                 //                             "totalFee": "-0.02236284"
                 //                         }
                 //                     ],
                 //                     "side": "buy",
                 //                     "quoteVolume": "37.2714",
                 //                     "profit": "-0.0007",
                 //                     "enterPointSource": "web",
                 //                     "tradeSide": "close",
                 //                     "posMode": "hedge_mode",
                 //                     "tradeScope": "taker",
                 //                     "cTime": "1700720700342"
                 //                 },
                 //             ],
                 //             "endId": "1099351587643699201"
                 //         }
                 //     }
                 //
                 // uta
                 //
                 //      {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1751099666579,
                 //         "data": {
                 //             "list": [
                 //                 {
                 //                     "execId": "1322441401010528257",
                 //                     "orderId": "1322441400976261120",
                 //                     "category": "USDT-FUTURES",
                 //                     "symbol": "BTCUSDT",
                 //                     "orderType": "market",
                 //                     "side": "sell",
                 //                     "execPrice": "107005.4",
                 //                     "execQty": "0.0001",
                 //                     "execValue": "10.7005",
                 //                     "tradeScope": "taker",
                 //                     "feeDetail": [{
                 //                         "feeCoin": "USDT",
                 //                         "fee":"0.00642032"
                 //                     }],
                 //                     "createdTime": "1751020520451",
                 //                     "updatedTime": "1751020520458",
                 //                     "execPnl": "0.00017"
                 //                 },
                 //             ],
                 //             "cursor": "1322061241878880257"
                 //         }
                 //     }
                 //
                 std::any data = this->safeValue(response, std::string("data"));
                 if (isTrue(isEqual(uta, true))) {
                   std::any fills =
                       this->safeList(data, std::string("list"), ccxt::list{});
                   return this->parseTrades(fills, market, since, limit);
                 } else if (isTrue(
                                (isTrue((isEqual(
                                     ::getValue(market, std::string("swap")),
                                     true))) ||
                                 isTrue((isEqual(
                                     ::getValue(market, std::string("future")),
                                     true)))))) {
                   std::any fills = this->safeList(
                       data, std::string("fillList"), ccxt::list{});
                   return this->parseTrades(fills, market, since, limit);
                 } else if (isTrue(!isEqual(marginMode, std::any{}))) {
                   std::any fills =
                       this->safeList(data, std::string("fills"), ccxt::list{});
                   return this->parseTrades(fills, market, since, limit);
                 }
                 return this->parseTrades(data, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name bitget#fetchPosition
   * @description fetch data on a single open contract trade position
   * @see https://www.bitget.com/api-doc/contract/position/get-single-position
   * @see https://www.bitget.com/api-doc/uta/trade/Get-Position
   * @param {string} symbol unified market symbol of the market the position is
   * held in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object} a [position structure]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<std::any>
  fetchPosition(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any productType = std::any{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response = std::any{};
                 std::any uta = std::any{};
                 std::any result = std::any{};
                 std::any utaparamsVariable =
                     awaitValue(this->handleUTAAndParams(
                         params, std::string("fetchPosition"), false));
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(isEqual(uta, true))) {
                   ::setValue(request, std::string("category"), productType);
                   response =
                       awaitValue(this->privateUtaGetV3PositionCurrentPosition(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "code": "00000",
                   //         "msg": "success",
                   //         "requestTime": 1750929905423,
                   //         "data": {
                   //             "list": [
                   //                 {
                   //                     "category": "USDT-FUTURES",
                   //                     "symbol": "BTCUSDT",
                   //                     "marginCoin": "USDT",
                   //                     "holdMode": "hedge_mode",
                   //                     "posSide": "long",
                   //                     "marginMode": "crossed",
                   //                     "positionBalance": "5.435199",
                   //                     "available": "0.001",
                   //                     "frozen": "0",
                   //                     "total": "0.001",
                   //                     "leverage": "20",
                   //                     "curRealisedPnl": "0",
                   //                     "avgPrice": "107410.3",
                   //                     "positionStatus": "normal",
                   //                     "unrealisedPnl": "0.0047",
                   //                     "liquidationPrice": "0",
                   //                     "mmr": "0.004",
                   //                     "profitRate": "0.0008647337475591",
                   //                     "markPrice": "107415.3",
                   //                     "breakEvenPrice": "107539.2",
                   //                     "totalFunding": "0",
                   //                     "openFeeTotal": "-0.06444618",
                   //                     "closeFeeTotal": "0",
                   //                     "createdTime": "1750495670699",
                   //                     "updatedTime": "1750929883465"
                   //                 }
                   //             ]
                   //         }
                   //     }
                   //
                   std::any data = this->safeDict(response, std::string("data"),
                                                  ccxt::dict{});
                   result =
                       this->safeList(data, std::string("list"), ccxt::list{});
                 } else {
                   ::setValue(request, std::string("marginCoin"),
                              ::getValue(market, std::string("settleId")));
                   ::setValue(request, std::string("productType"), productType);
                   response = awaitValue(
                       this->privateMixGetV2MixPositionSinglePosition(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "code": "00000",
                   //         "msg": "success",
                   //         "requestTime": 1700807531673,
                   //         "data": [
                   //             {
                   //                 "marginCoin": "USDT",
                   //                 "symbol": "BTCUSDT",
                   //                 "holdSide": "long",
                   //                 "openDelegateSize": "0",
                   //                 "marginSize": "3.73555",
                   //                 "available": "0.002",
                   //                 "locked": "0",
                   //                 "total": "0.002",
                   //                 "leverage": "20",
                   //                 "achievedProfits": "0",
                   //                 "openPriceAvg": "37355.5",
                   //                 "marginMode": "crossed",
                   //                 "posMode": "hedge_mode",
                   //                 "unrealizedPL": "0.007",
                   //                 "liquidationPrice": "31724.970702417",
                   //                 "keepMarginRate": "0.004",
                   //                 "markPrice": "37359",
                   //                 "marginRatio": "0.029599540355",
                   //                 "cTime": "1700807507275"
                   //             }
                   //         ]
                   //     }
                   //
                   result = this->safeList(response, std::string("data"),
                                           ccxt::list{});
                 }
                 std::any first = this->safeDict(result, 0, ccxt::dict{});
                 return this->parsePosition(first, market);
               })
        .share();
  }

  /**
   * @method
   * @name bitget#fetchPositions
   * @description fetch all open positions
   * @see https://www.bitget.com/api-doc/contract/position/get-all-position
   * @see https://www.bitget.com/api-doc/contract/position/Get-History-Position
   * @see https://www.bitget.com/api-doc/uta/trade/Get-Position
   * @param {string[]} [symbols] list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginCoin] the settle currency of the positions,
   * needs to match the productType
   * @param {string} [params.productType] 'USDT-FUTURES', 'USDC-FUTURES',
   * 'COIN-FUTURES', 'SUSDT-FUTURES', 'SUSDC-FUTURES' or 'SCOIN-FUTURES'
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @param {boolean} [params.useHistoryEndpoint] default false, when true  will
   * use the historic endpoint to fetch positions
   * @param {string} [params.method] either (default)
   * 'privateMixGetV2MixPositionAllPosition',
   * 'privateMixGetV2MixPositionHistoryPosition', or
   * 'privateUtaGetV3PositionCurrentPosition'
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object[]} a list of [position structure]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<std::any>
  fetchPositions(std::any symbols = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any paginate = false;
                std::any paginateparamsVariable = this->handleOptionAndParams(
                    params, std::string("fetchPositions"),
                    std::string("paginate"));
                paginate = ::getValue(paginateparamsVariable, 0);
                params = ::getValue(paginateparamsVariable, 1);
                if (isTrue(paginate)) {
                  return awaitValue(this->fetchPaginatedCallCursor(
                      std::string("fetchPositions"), std::any{}, std::any{},
                      std::any{}, params, std::string("endId"),
                      std::string("idLessThan")));
                }
                std::any method = std::any{};
                std::any useHistoryEndpoint = this->safeBool(
                    params, std::string("useHistoryEndpoint"), false);
                if (isTrue(isEqual(useHistoryEndpoint, true))) {
                  method =
                      std::string("privateMixGetV2MixPositionHistoryPosition");
                } else {
                  std::any methodparamsVariable = this->handleOptionAndParams(
                      params, std::string("fetchPositions"),
                      std::string("method"),
                      std::string("privateMixGetV2MixPositionAllPosition"));
                  method = ::getValue(methodparamsVariable, 0);
                  params = ::getValue(methodparamsVariable, 1);
                }
                std::any market = std::any{};
                if (isTrue(!isEqual(symbols, std::any{}))) {
                  std::any first = this->safeString(symbols, 0);
                  // symbols can be undefined or []
                  if (isTrue(!isEqual(first, std::any{}))) {
                    market = this->market(first);
                  }
                }
                std::any productType = std::any{};
                std::any productTypeparamsVariable =
                    this->handleProductTypeAndParams(market, params);
                productType = ::getValue(productTypeparamsVariable, 0);
                params = ::getValue(productTypeparamsVariable, 1);
                std::any request = ccxt::dict{};
                std::any response = std::any{};
                std::any isHistory = false;
                std::any uta = std::any{};
                std::any utaparamsVariable =
                    awaitValue(this->handleUTAAndParams(
                        params, std::string("fetchPositions"), false));
                uta = ::getValue(utaparamsVariable, 0);
                params = ::getValue(utaparamsVariable, 1);
                if (isTrue(isEqual(uta, true))) {
                  ::setValue(request, std::string("category"), productType);
                  response =
                      awaitValue(this->privateUtaGetV3PositionCurrentPosition(
                          this->extend(request, params)));
                } else if (isTrue(isEqual(
                               method,
                               std::string(
                                   "privateMixGetV2MixPositionAllPosition")))) {
                  std::any marginCoin = this->safeString(
                      params, std::string("marginCoin"), std::string("USDT"));
                  if (isTrue(!isEqual(market, std::any{}))) {
                    marginCoin = ::getValue(market, std::string("settleId"));
                  } else if (isTrue(isEqual(productType,
                                            std::string("USDT-FUTURES")))) {
                    marginCoin = std::string("USDT");
                  } else if (isTrue(isEqual(productType,
                                            std::string("USDC-FUTURES")))) {
                    marginCoin = std::string("USDC");
                  } else if (isTrue(isEqual(productType,
                                            std::string("SUSDT-FUTURES")))) {
                    marginCoin = std::string("SUSDT");
                  } else if (isTrue(isEqual(productType,
                                            std::string("SUSDC-FUTURES")))) {
                    marginCoin = std::string("SUSDC");
                  } else if (isTrue(isTrue((isEqual(
                                        productType,
                                        std::string("SCOIN-FUTURES")))) ||
                                    isTrue((isEqual(
                                        productType,
                                        std::string("COIN-FUTURES")))))) {
                    if (isTrue(isEqual(marginCoin, std::any{}))) {
                      throw ArgumentsRequired(toString(
                          add(this->id,
                              std::string(
                                  " fetchPositions() requires a marginCoin "
                                  "parameter that matches the productType"))));
                    }
                  }
                  ::setValue(request, std::string("marginCoin"), marginCoin);
                  ::setValue(request, std::string("productType"), productType);
                  response =
                      awaitValue(this->privateMixGetV2MixPositionAllPosition(
                          this->extend(request, params)));
                } else {
                  isHistory = true;
                  if (isTrue(!isEqual(market, std::any{}))) {
                    ::setValue(request, std::string("symbol"),
                               ::getValue(market, std::string("id")));
                  }
                  ::setValue(request, std::string("productType"), productType);
                  response = awaitValue(
                      this->privateMixGetV2MixPositionHistoryPosition(
                          this->extend(request, params)));
                }
                //
                // privateMixGetV2MixPositionAllPosition
                //
                //     {
                //         "code": "00000",
                //         "msg": "success",
                //         "requestTime": 1700807810221,
                //         "data": [
                //             {
                //                 "marginCoin": "USDT",
                //                 "symbol": "BTCUSDT",
                //                 "holdSide": "long",
                //                 "openDelegateSize": "0",
                //                 "marginSize": "3.73555",
                //                 "available": "0.002",
                //                 "locked": "0",
                //                 "total": "0.002",
                //                 "leverage": "20",
                //                 "achievedProfits": "0",
                //                 "openPriceAvg": "37355.5",
                //                 "marginMode": "crossed",
                //                 "posMode": "hedge_mode",
                //                 "unrealizedPL": "0.03",
                //                 "liquidationPrice": "31725.023602417",
                //                 "keepMarginRate": "0.004",
                //                 "markPrice": "37370.5",
                //                 "marginRatio": "0.029550120396",
                //                 "cTime": "1700807507275"
                //             }
                //         ]
                //     }
                //
                // privateMixGetV2MixPositionHistoryPosition
                //
                //     {
                //         "code": "00000",
                //         "msg": "success",
                //         "requestTime": 1700808051002,
                //         "data": {
                //             "list": [
                //                 {
                //                     "symbol": "BTCUSDT",
                //                     "marginCoin": "USDT",
                //                     "holdSide": "long",
                //                     "openAvgPrice": "37272.1",
                //                     "closeAvgPrice": "37271.4",
                //                     "marginMode": "crossed",
                //                     "openTotalPos": "0.001",
                //                     "closeTotalPos": "0.001",
                //                     "pnl": "-0.0007",
                //                     "netProfit": "-0.0454261",
                //                     "totalFunding": "0",
                //                     "openFee": "-0.02236326",
                //                     "closeFee": "-0.02236284",
                //                     "utime": "1700720700400",
                //                     "ctime": "1700720651684"
                //                 },
                //             ],
                //             "endId": "1099351653866962944"
                //         }
                //     }
                //
                // privateUtaGetV3PositionCurrentPosition
                //
                //     {
                //         "code": "00000",
                //         "msg": "success",
                //         "requestTime": 1750929905423,
                //         "data": {
                //             "list": [
                //                 {
                //                     "category": "USDT-FUTURES",
                //                     "symbol": "BTCUSDT",
                //                     "marginCoin": "USDT",
                //                     "holdMode": "hedge_mode",
                //                     "posSide": "long",
                //                     "marginMode": "crossed",
                //                     "positionBalance": "5.435199",
                //                     "available": "0.001",
                //                     "frozen": "0",
                //                     "total": "0.001",
                //                     "leverage": "20",
                //                     "curRealisedPnl": "0",
                //                     "avgPrice": "107410.3",
                //                     "positionStatus": "normal",
                //                     "unrealisedPnl": "0.0047",
                //                     "liquidationPrice": "0",
                //                     "mmr": "0.004",
                //                     "profitRate": "0.0008647337475591",
                //                     "markPrice": "107415.3",
                //                     "breakEvenPrice": "107539.2",
                //                     "totalFunding": "0",
                //                     "openFeeTotal": "-0.06444618",
                //                     "closeFeeTotal": "0",
                //                     "createdTime": "1750495670699",
                //                     "updatedTime": "1750929883465"
                //                 }
                //             ]
                //         }
                //     }
                //
                std::any position = ccxt::list{};
                if (isTrue(isTrue((isEqual(uta, true))) || isTrue(isHistory))) {
                  std::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                  position =
                      this->safeList(data, std::string("list"), ccxt::list{});
                } else {
                  position = this->safeList(response, std::string("data"),
                                            ccxt::list{});
                }
                std::any result = ccxt::list{};
                for (std::any i = 0; isLessThan(i, getArrayLength(position));
                     postFixIncrement(i)) {
                  arrayPush(result, this->parsePosition(::getValue(position, i),
                                                        market));
                }
                symbols = this->marketSymbols(symbols);
                return this->filterByArrayPositions(
                    result, std::string("symbol"), symbols, false);
              })
            .share();
  }

  std::any parsePosition(std::any position,
                         std::any market = std::any{}) override {
    //
    // fetchPosition
    //
    //     {
    //         "marginCoin": "USDT",
    //         "symbol": "BTCUSDT",
    //         "holdSide": "long",
    //         "openDelegateSize": "0",
    //         "marginSize": "3.73555",
    //         "available": "0.002",
    //         "locked": "0",
    //         "total": "0.002",
    //         "leverage": "20",
    //         "achievedProfits": "0",
    //         "openPriceAvg": "37355.5",
    //         "marginMode": "crossed",
    //         "posMode": "hedge_mode",
    //         "unrealizedPL": "0.007",
    //         "liquidationPrice": "31724.970702417",
    //         "keepMarginRate": "0.004",
    //         "markPrice": "37359",
    //         "marginRatio": "0.029599540355",
    //         "cTime": "1700807507275"
    //     }
    //
    // uta: fetchPosition
    //
    //     {
    //         "category": "USDT-FUTURES",
    //         "symbol": "BTCUSDT",
    //         "marginCoin": "USDT",
    //         "holdMode": "hedge_mode",
    //         "posSide": "long",
    //         "marginMode": "crossed",
    //         "positionBalance": "5.435199",
    //         "available": "0.001",
    //         "frozen": "0",
    //         "total": "0.001",
    //         "leverage": "20",
    //         "curRealisedPnl": "0",
    //         "avgPrice": "107410.3",
    //         "positionStatus": "normal",
    //         "unrealisedPnl": "0.0047",
    //         "liquidationPrice": "0",
    //         "mmr": "0.004",
    //         "profitRate": "0.0008647337475591",
    //         "markPrice": "107415.3",
    //         "breakEvenPrice": "107539.2",
    //         "totalFunding": "0",
    //         "openFeeTotal": "-0.06444618",
    //         "closeFeeTotal": "0",
    //         "createdTime": "1750495670699",
    //         "updatedTime": "1750929883465"
    //     }
    //
    // fetchPositions: privateMixGetV2MixPositionAllPosition
    //
    //     {
    //         "marginCoin": "USDT",
    //         "symbol": "BTCUSDT",
    //         "holdSide": "long",
    //         "openDelegateSize": "0",
    //         "marginSize": "3.73555",
    //         "available": "0.002",
    //         "locked": "0",
    //         "total": "0.002",
    //         "leverage": "20",
    //         "achievedProfits": "0",
    //         "openPriceAvg": "37355.5",
    //         "marginMode": "crossed",
    //         "posMode": "hedge_mode",
    //         "unrealizedPL": "0.03",
    //         "liquidationPrice": "31725.023602417",
    //         "keepMarginRate": "0.004",
    //         "markPrice": "37370.5",
    //         "marginRatio": "0.029550120396",
    //         "cTime": "1700807507275"
    //     }
    //
    // fetchPositionsHistory: privateMixGetV2MixPositionHistoryPosition
    //
    //     {
    //         "symbol": "BTCUSDT",
    //         "marginCoin": "USDT",
    //         "holdSide": "long",
    //         "openAvgPrice": "37272.1",
    //         "closeAvgPrice": "37271.4",
    //         "marginMode": "crossed",
    //         "openTotalPos": "0.001",
    //         "closeTotalPos": "0.001",
    //         "pnl": "-0.0007",
    //         "netProfit": "-0.0454261",
    //         "totalFunding": "0",
    //         "openFee": "-0.02236326",
    //         "closeFee": "-0.02236284",
    //         "utime": "1700720700400",
    //         "ctime": "1700720651684"
    //     }
    //
    // closeAllPositions
    //
    //     {
    //         "orderId": "1120923953904893955",
    //         "clientOid": "1120923953904893956"
    //     }
    //
    // uta: fetchPositionsHistory
    //
    //     {
    //         "positionId": "1322441328637100049",
    //         "category": "USDT-FUTURES",
    //         "symbol": "BTCUSDT",
    //         "marginCoin": "USDT",
    //         "holdMode": "hedge_mode",
    //         "posSide": "long",
    //         "marginMode": "crossed",
    //         "openPriceAvg": "107003.7",
    //         "closePriceAvg": "107005.4",
    //         "openTotalPos": "0.0001",
    //         "closeTotalPos": "0.0001",
    //         "cumRealisedPnl": "0.00017",
    //         "netProfit": "-0.01267055",
    //         "totalFunding": "0",
    //         "openFeeTotal": "-0.00642022",
    //         "closeFeeTotal": "-0.00642032",
    //         "createdTime": "1751020503195",
    //         "updatedTime": "1751020520458"
    //     }
    //
    std::any marketId = this->safeString(position, std::string("symbol"));
    market =
        this->safeMarket(marketId, market, std::any{}, std::string("contract"));
    std::any symbol = ::getValue(market, std::string("symbol"));
    std::any timestamp = this->safeIntegerN(
        position, ccxt::list{std::string("cTime"), std::string("ctime"),
                             std::string("createdTime")});
    std::any marginMode = this->safeString(position, std::string("marginMode"));
    std::any collateral = std::any{};
    std::any initialMargin = std::any{};
    std::any unrealizedPnl = this->safeString2(
        position, std::string("unrealizedPL"), std::string("unrealisedPnl"));
    std::any rawCollateral = this->safeString2(
        position, std::string("marginSize"), std::string("positionBalance"));
    if (isTrue(isEqual(marginMode, std::string("isolated")))) {
      collateral = ccxt::Precise::stringAdd(rawCollateral, unrealizedPnl);
    } else if (isTrue(isEqual(marginMode, std::string("crossed")))) {
      marginMode = std::string("cross");
      initialMargin = rawCollateral;
    }
    std::any holdMode = this->safeString2(position, std::string("posMode"),
                                          std::string("holdMode"));
    std::any hedged = std::any{};
    if (isTrue(isEqual(holdMode, std::string("hedge_mode")))) {
      hedged = true;
    } else if (isTrue(isEqual(holdMode, std::string("one_way_mode")))) {
      hedged = false;
    }
    std::any side = this->safeString2(position, std::string("holdSide"),
                                      std::string("posSide"));
    std::any leverage = this->safeString(position, std::string("leverage"));
    std::any contractSizeNumber =
        this->safeValue(market, std::string("contractSize"));
    std::any contractSize = this->numberToString(contractSizeNumber);
    std::any baseAmount = this->safeString2(position, std::string("total"),
                                            std::string("openTotalPos"));
    std::any entryPrice =
        this->safeStringN(position, ccxt::list{std::string("openPriceAvg"),
                                               std::string("openAvgPrice"),
                                               std::string("avgPrice")});
    std::any maintenanceMarginPercentage =
        this->safeString(position, std::string("keepMarginRate"));
    std::any openNotional = ccxt::Precise::stringMul(entryPrice, baseAmount);
    if (isTrue(isEqual(initialMargin, std::any{}))) {
      initialMargin = ccxt::Precise::stringDiv(openNotional, leverage);
    }
    std::any contracts =
        this->parseNumber(ccxt::Precise::stringDiv(baseAmount, contractSize));
    if (isTrue(isEqual(contracts, std::any{}))) {
      contracts = this->safeNumber(position, std::string("closeTotalPos"));
    }
    std::any markPrice = this->safeString(position, std::string("markPrice"));
    std::any notional = ccxt::Precise::stringMul(baseAmount, markPrice);
    std::any initialMarginPercentage =
        ccxt::Precise::stringDiv(initialMargin, notional);
    std::any liquidationPrice = this->parseNumber(this->omitZero(
        this->safeString(position, std::string("liquidationPrice"))));
    std::any calcTakerFeeRate = std::string("0.0006");
    std::any calcTakerFeeMult = std::string("0.9994");
    if (isTrue(isTrue(isTrue((isEqual(liquidationPrice, std::any{}))) &&
                      isTrue((isEqual(marginMode, std::string("isolated"))))) &&
               isTrue(ccxt::Precise::stringGt(baseAmount, std::string("0"))))) {
      std::any signedMargin =
          ccxt::Precise::stringDiv(rawCollateral, baseAmount);
      std::any signedMmp = maintenanceMarginPercentage;
      if (isTrue(isEqual(side, std::string("short")))) {
        signedMargin = ccxt::Precise::stringNeg(signedMargin);
        signedMmp = ccxt::Precise::stringNeg(signedMmp);
      }
      std::any mmrMinusOne =
          ccxt::Precise::stringSub(std::string("1"), signedMmp);
      std::any numerator = ccxt::Precise::stringSub(entryPrice, signedMargin);
      if (isTrue(isEqual(side, std::string("long")))) {
        mmrMinusOne = ccxt::Precise::stringMul(mmrMinusOne, calcTakerFeeMult);
      } else {
        numerator = ccxt::Precise::stringMul(numerator, calcTakerFeeMult);
      }
      liquidationPrice =
          this->parseNumber(ccxt::Precise::stringDiv(numerator, mmrMinusOne));
    }
    std::any feeToClose = ccxt::Precise::stringMul(notional, calcTakerFeeRate);
    std::any maintenanceMargin = ccxt::Precise::stringAdd(
        ccxt::Precise::stringMul(maintenanceMarginPercentage, notional),
        feeToClose);
    std::any percentage = ccxt::Precise::stringMul(
        ccxt::Precise::stringDiv(unrealizedPnl, initialMargin, 4),
        std::string("100"));
    return this->safePosition(ccxt::dict{
        {std::string("info"), position},
        {std::string("id"), this->safeString2(position, std::string("orderId"),
                                              std::string("positionId"))},
        {std::string("symbol"), symbol},
        {std::string("notional"), this->parseNumber(notional)},
        {std::string("marginMode"), marginMode},
        {std::string("liquidationPrice"), liquidationPrice},
        {std::string("entryPrice"), this->parseNumber(entryPrice)},
        {std::string("unrealizedPnl"), this->parseNumber(unrealizedPnl)},
        {std::string("realizedPnl"),
         this->safeNumberN(position,
                           ccxt::list{std::string("pnl"),
                                      std::string("curRealisedPnl"),
                                      std::string("cumRealisedPnl")})},
        {std::string("percentage"), this->parseNumber(percentage)},
        {std::string("contracts"), contracts},
        {std::string("contractSize"), contractSizeNumber},
        {std::string("markPrice"), this->parseNumber(markPrice)},
        {std::string("lastPrice"),
         this->safeNumber2(position, std::string("closeAvgPrice"),
                           std::string("closePriceAvg"))},
        {std::string("side"), side},
        {std::string("hedged"), hedged},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("lastUpdateTimestamp"),
         this->safeInteger2(position, std::string("utime"),
                            std::string("updatedTime"))},
        {std::string("maintenanceMargin"),
         this->parseNumber(maintenanceMargin)},
        {std::string("maintenanceMarginPercentage"),
         this->parseNumber(maintenanceMarginPercentage)},
        {std::string("collateral"), this->parseNumber(collateral)},
        {std::string("initialMargin"), this->parseNumber(initialMargin)},
        {std::string("initialMarginPercentage"),
         this->parseNumber(initialMarginPercentage)},
        {std::string("leverage"), this->parseNumber(leverage)},
        {std::string("marginRatio"),
         this->safeNumber2(position, std::string("marginRatio"),
                           std::string("mmr"))},
        {std::string("stopLossPrice"), std::any{}},
        {std::string("takeProfitPrice"), std::any{}},
    });
  }

  /**
   * @method
   * @name bitget#fetchFundingRateHistory
   * @description fetches historical funding rate prices
   * @see
   * https://www.bitget.com/api-doc/contract/market/Get-History-Funding-Rate
   * @see https://www.bitget.com/api-doc/uta/public/Get-History-Funding-Rate
   * @param {string} symbol unified symbol of the market to fetch the funding
   * rate history for
   * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
   * @param {int} [limit] the maximum amount of funding rate structures to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure}
   */
  std::shared_future<std::any> fetchFundingRateHistory(
      std::any symbol = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any productType = std::any{};
                 std::any uta = std::any{};
                 std::any response = std::any{};
                 std::any result = std::any{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any utaparamsVariable =
                     awaitValue(this->handleUTAAndParams(
                         params, std::string("fetchFundingRateHistory"),
                         false));
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(isEqual(uta, true))) {
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(request, std::string("limit"), limit);
                   }
                   ::setValue(request, std::string("category"), productType);
                   response =
                       awaitValue(this->publicUtaGetV3MarketHistoryFundRate(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "code": "00000",
                   //         "msg": "success",
                   //         "requestTime": 1750435113658,
                   //         "data": {
                   //             "resultList": [
                   //                 {
                   //                     "symbol": "BTCUSDT",
                   //                     "fundingRate": "-0.000017",
                   //                     "fundingRateTimestamp":
                   //                     "1750431600000"
                   //                 },
                   //             ]
                   //         }
                   //     }
                   //
                   std::any data = this->safeDict(response, std::string("data"),
                                                  ccxt::dict{});
                   result = this->safeList(data, std::string("resultList"),
                                           ccxt::list{});
                 } else {
                   std::any paginate = false;
                   std::any paginateparamsVariable =
                       this->handleOptionAndParams(
                           params, std::string("fetchFundingRateHistory"),
                           std::string("paginate"));
                   paginate = ::getValue(paginateparamsVariable, 0);
                   params = ::getValue(paginateparamsVariable, 1);
                   if (isTrue(paginate)) {
                     return awaitValue(this->fetchPaginatedCallIncremental(
                         std::string("fetchFundingRateHistory"), symbol, since,
                         limit, params, std::string("pageNo"), 100));
                   }
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(request, std::string("pageSize"), limit);
                   }
                   ::setValue(request, std::string("productType"), productType);
                   response =
                       awaitValue(this->publicMixGetV2MixMarketHistoryFundRate(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "code": "00000",
                   //         "msg": "success",
                   //         "requestTime": 1652406728393,
                   //         "data": [
                   //             {
                   //                 "symbol": "BTCUSDT",
                   //                 "fundingRate": "-0.0003",
                   //                 "fundingTime": "1652396400000"
                   //             },
                   //         ]
                   //     }
                   //
                   result = this->safeList(response, std::string("data"),
                                           ccxt::list{});
                 }
                 std::any rates = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(result));
                      postFixIncrement(i)) {
                   std::any entry = ::getValue(result, i);
                   std::any marketId =
                       this->safeString(entry, std::string("symbol"));
                   std::any symbolInner = this->safeSymbol(marketId, market);
                   std::any timestamp =
                       this->safeInteger2(entry, std::string("fundingTime"),
                                          std::string("fundingRateTimestamp"));
                   arrayPush(
                       rates,
                       ccxt::dict{
                           {std::string("info"), entry},
                           {std::string("symbol"), symbolInner},
                           {std::string("fundingRate"),
                            this->safeNumber(entry,
                                             std::string("fundingRate"))},
                           {std::string("timestamp"), timestamp},
                           {std::string("datetime"), this->iso8601(timestamp)},
                       });
                 }
                 std::any sorted =
                     this->sortBy(rates, std::string("timestamp"));
                 return this->filterBySymbolSinceLimit(
                     sorted, ::getValue(market, std::string("symbol")), since,
                     limit);
               })
        .share();
  }

  /**
   * @method
   * @name bitget#fetchFundingRate
   * @description fetch the current funding rate
   * @see
   * https://www.bitget.com/api-doc/contract/market/Get-Current-Funding-Rate
   * @see
   * https://www.bitget.com/api-doc/contract/market/Get-Symbol-Next-Funding-Time
   * @see https://www.bitget.com/api-doc/uta/public/Get-Current-Funding-Rate
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @param {string} [params.method] either (default)
   * 'publicMixGetV2MixMarketCurrentFundRate' or
   * 'publicMixGetV2MixMarketFundingTime'
   * @returns {object} a [funding rate structure]{@link
   * https://docs.ccxt.com/?id=funding-rate-structure}
   */
  std::shared_future<std::any>
  fetchFundingRate(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("swap")),
                                     true))) {
                   throw BadSymbol(toString(
                       add(this->id, std::string(" fetchFundingRate() supports "
                                                 "swap contracts only"))));
                 }
                 std::any productType = std::any{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any uta = std::any{};
                 std::any response = std::any{};
                 std::any utaparamsVariable =
                     awaitValue(this->handleUTAAndParams(
                         params, std::string("fetchFundingRate"), false));
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(isEqual(uta, true))) {
                   response =
                       awaitValue(this->publicUtaGetV3MarketCurrentFundRate(
                           this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("productType"), productType);
                   std::any method = std::any{};
                   std::any methodparamsVariable = this->handleOptionAndParams(
                       params, std::string("fetchFundingRate"),
                       std::string("method"),
                       std::string("publicMixGetV2MixMarketCurrentFundRate"));
                   method = ::getValue(methodparamsVariable, 0);
                   params = ::getValue(methodparamsVariable, 1);
                   if (isTrue(isEqual(
                           method,
                           std::string(
                               "publicMixGetV2MixMarketCurrentFundRate")))) {
                     response = awaitValue(
                         this->publicMixGetV2MixMarketCurrentFundRate(
                             this->extend(request, params)));
                   } else if (isTrue(isEqual(
                                  method,
                                  std::string(
                                      "publicMixGetV2MixMarketFundingTime")))) {
                     response =
                         awaitValue(this->publicMixGetV2MixMarketFundingTime(
                             this->extend(request, params)));
                   }
                 }
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseFundingRate(::getValue(data, 0), market);
               })
        .share();
  }

  /**
   * @method
   * @name bitget#fetchFundingRates
   * @description fetch the current funding rates for all markets
   * @see https://www.bitget.com/api-doc/contract/market/Get-All-Symbol-Ticker
   * @param {string[]} [symbols] list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.subType] *contract only* 'linear', 'inverse'
   * @param {string} [params.productType] *contract only* 'USDT-FUTURES',
   * 'USDC-FUTURES', 'COIN-FUTURES', 'SUSDT-FUTURES', 'SUSDC-FUTURES' or
   * 'SCOIN-FUTURES'
   * @param {string} [params.method] either (default)
   * 'publicMixGetV2MixMarketTickers' or
   * 'publicMixGetV2MixMarketCurrentFundRate'
   * @returns {object} a dictionary of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rates-structure}, indexed by market
   * symbols
   */
  std::shared_future<std::any>
  fetchFundingRates(std::any symbols = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbols, std::any{}))) {
                   std::any symbol = this->safeValue(symbols, 0);
                   market = this->market(symbol);
                 }
                 std::any request = ccxt::dict{};
                 std::any productType = std::any{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any method =
                     std::string("publicMixGetV2MixMarketTickers");
                 std::any methodparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingRates"),
                     std::string("method"), method);
                 method = ::getValue(methodparamsVariable, 0);
                 params = ::getValue(methodparamsVariable, 1);
                 std::any response = std::any{};
                 ::setValue(request, std::string("productType"), productType);
                 if (isTrue(isEqual(
                         method,
                         std::string("publicMixGetV2MixMarketTickers")))) {
                   // {
                   //     "code": "00000",
                   //     "msg": "success",
                   //     "requestTime": 1700533773477,
                   //     "data": [
                   //         {
                   //             "symbol": "BTCUSD",
                   //             "lastPr": "29904.5",
                   //             "askPr": "29904.5",
                   //             "bidPr": "29903.5",
                   //             "bidSz": "0.5091",
                   //             "askSz": "2.2694",
                   //             "high24h": "0",
                   //             "low24h": "0",
                   //             "ts": "1695794271400",
                   //             "change24h": "0",
                   //             "baseVolume": "0",
                   //             "quoteVolume": "0",
                   //             "usdtVolume": "0",
                   //             "openUtc": "0",
                   //             "changeUtc24h": "0",
                   //             "indexPrice": "29132.353333",
                   //             "fundingRate": "-0.0007",
                   //             "holdingAmount": "125.6844",
                   //             "deliveryStartTime": null,
                   //             "deliveryTime": null,
                   //             "deliveryStatus": "delivery_normal",
                   //             "open24h": "0",
                   //             "markPrice": "12345"
                   //         },
                   //     ]
                   // }
                   response = awaitValue(this->publicMixGetV2MixMarketTickers(
                       this->extend(request, params)));
                 } else if (isTrue(isEqual(method,
                                           std::string("publicMixGetV2MixMarket"
                                                       "CurrentFundRate")))) {
                   //
                   //     {
                   //         "code": "00000",
                   //         "msg": "success",
                   //         "requestTime":1761659449917,
                   //         "data":[
                   //             {
                   //                 "symbol": "BTCUSDT",
                   //                 "fundingRate": "-0.000024",
                   //                 "fundingRateInterval": "8",
                   //                 "nextUpdate": "1761667200000",
                   //                 "minFundingRate": "-0.003",
                   //                 "maxFundingRate": "0.003"
                   //             }
                   //         ]
                   //     }
                   //
                   response =
                       awaitValue(this->publicMixGetV2MixMarketCurrentFundRate(
                           this->extend(request, params)));
                 }
                 symbols = this->marketSymbols(symbols);
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseFundingRates(data, symbols);
               })
        .share();
  }

  /**
   * @method
   * @name bitget#fetchFundingIntervals
   * @description fetch the funding rate interval for multiple markets
   * @see https://www.bitget.com/api-doc/contract/market/Get-All-Symbol-Ticker
   * @param {string[]} [symbols] list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.productType] 'USDT-FUTURES' (default),
   * 'USDC-FUTURES', 'COIN-FUTURES', 'SUSDT-FUTURES', 'SUSDC-FUTURES' or
   * 'SCOIN-FUTURES'
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-structure}
   */
  std::shared_future<std::any>
  fetchFundingIntervals(std::any symbols = std::any{},
                        std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        params = this->extend(
                            ccxt::dict{
                                {std::string("method"),
                                 std::string(
                                     "publicMixGetV2MixMarketCurrentFundRate")},
                            },
                            params);
                        return awaitValue(
                            this->fetchFundingRates(symbols, params));
                      })
        .share();
  }

  std::any parseFundingRate(std::any contract,
                            std::any market = std::any{}) override {
    //
    // fetchFundingRate: publicMixGetV2MixMarketCurrentFundRate,
    // publicUtaGetV3MarketCurrentFundRate
    //
    //     {
    //         "symbol": "BTCUSDT",
    //         "fundingRate": "-0.000013",
    //         "fundingRateInterval": "8",
    //         "nextUpdate": "1745510400000",
    //         "minFundingRate": "-0.003",
    //         "maxFundingRate": "0.003"
    //     }
    //
    // fetchFundingRate: publicMixGetV2MixMarketFundingTime
    //
    //     {
    //         "symbol": "BTCUSDT",
    //         "nextFundingTime": "1745424000000",
    //         "ratePeriod": "8"
    //     }
    //
    // fetchFundingInterval
    //
    //     {
    //         "symbol": "BTCUSDT",
    //         "nextFundingTime": "1727942400000",
    //         "ratePeriod": "8"
    //     }
    //
    // fetchFundingRates
    //
    //     {
    //         "symbol": "BTCUSD",
    //         "lastPr": "29904.5",
    //         "askPr": "29904.5",
    //         "bidPr": "29903.5",
    //         "bidSz": "0.5091",
    //         "askSz": "2.2694",
    //         "high24h": "0",
    //         "low24h": "0",
    //         "ts": "1695794271400",
    //         "change24h": "0",
    //         "baseVolume": "0",
    //         "quoteVolume": "0",
    //         "usdtVolume": "0",
    //         "openUtc": "0",
    //         "changeUtc24h": "0",
    //         "indexPrice": "29132.353333",
    //         "fundingRate": "-0.0007",
    //         "holdingAmount": "125.6844",
    //         "deliveryStartTime": null,
    //         "deliveryTime": null,
    //         "deliveryStatus": "delivery_normal",
    //         "open24h": "0",
    //         "markPrice": "12345"
    //     }
    //
    std::any marketId = this->safeString(contract, std::string("symbol"));
    std::any symbol =
        this->safeSymbol(marketId, market, std::any{}, std::string("swap"));
    std::any fundingTimestamp = this->safeInteger2(
        contract, std::string("nextFundingTime"), std::string("nextUpdate"));
    std::any interval = this->safeString2(contract, std::string("ratePeriod"),
                                          std::string("fundingRateInterval"));
    std::any timestamp = this->safeInteger(contract, std::string("ts"));
    std::any markPrice = this->safeNumber(contract, std::string("markPrice"));
    std::any indexPrice = this->safeNumber(contract, std::string("indexPrice"));
    std::any intervalString = std::any{};
    if (isTrue(!isEqual(interval, std::any{}))) {
      intervalString = add(interval, std::string("h"));
    }
    return ccxt::dict{
        {std::string("info"), contract},
        {std::string("symbol"), symbol},
        {std::string("markPrice"), markPrice},
        {std::string("indexPrice"), indexPrice},
        {std::string("interestRate"), std::any{}},
        {std::string("estimatedSettlePrice"), std::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("fundingRate"),
         this->safeNumber(contract, std::string("fundingRate"))},
        {std::string("fundingTimestamp"), fundingTimestamp},
        {std::string("fundingDatetime"), this->iso8601(fundingTimestamp)},
        {std::string("nextFundingRate"), std::any{}},
        {std::string("nextFundingTimestamp"), std::any{}},
        {std::string("nextFundingDatetime"), std::any{}},
        {std::string("previousFundingRate"), std::any{}},
        {std::string("previousFundingTimestamp"), std::any{}},
        {std::string("previousFundingDatetime"), std::any{}},
        {std::string("interval"), intervalString},
    };
  }

  /**
   * @method
   * @name bitget#fetchFundingHistory
   * @description fetch the funding history
   * @see https://www.bitget.com/api-doc/contract/account/Get-Account-Bill
   * @param {string} symbol unified market symbol
   * @param {int} [since] the starting timestamp in milliseconds
   * @param {int} [limit] the number of entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch funding history
   * for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object[]} a list of [funding history structures]{@link
   * https://docs.ccxt.com/?id=funding-history-structure}
   */
  std::shared_future<std::any>
  fetchFundingHistory(std::any symbol = std::any{}, std::any since = std::any{},
                      std::any limit = std::any{},
                      std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingHistory() requires "
                                             "a symbol argument"))));
                 }
                 std::any uta = std::any{};
                 std::any utaparamsVariable =
                     awaitValue(this->handleUTAAndParams(
                         params, std::string("fetchFundingHistory"), false));
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingHistory"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   if (isTrue(isEqual(uta, true))) {
                     return awaitValue(this->fetchPaginatedCallCursor(
                         std::string("fetchFundingHistory"), symbol, since,
                         limit, params, std::string("cursor"),
                         std::string("cursor")));
                   }
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchFundingHistory"), symbol, since, limit,
                       params, std::string("endId"),
                       std::string("idLessThan")));
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("swap")),
                                     true))) {
                   throw BadSymbol(toString(add(
                       this->id, std::string(" fetchFundingHistory() supports "
                                             "swap contracts only"))));
                 }
                 std::any productType = std::any{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any request = ccxt::dict{};
                 std::any requestparamsVariable = this->handleUntilOption(
                     std::string("endTime"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(uta, true))) {
                   ::setValue(request, std::string("coin"),
                              ::getValue(market, std::string("settleId")));
                   ::setValue(request, std::string("category"), productType);
                   response =
                       awaitValue(this->privateUtaGetV3AccountFinancialRecords(
                           this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   ::setValue(request, std::string("marginCoin"),
                              ::getValue(market, std::string("settleId")));
                   ::setValue(request, std::string("businessType"),
                              std::string("contract_settle_fee"));
                   ::setValue(request, std::string("productType"), productType);
                   response = awaitValue(this->privateMixGetV2MixAccountBill(
                       this->extend(request, params)));
                 }
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::dict{});
                 std::any bills =
                     this->safeList2(data, std::string("bills"),
                                     std::string("list"), ccxt::list{});
                 if (isTrue(isEqual(uta, true))) {
                   bills = this->filterByArray(
                       bills, std::string("type"),
                       ccxt::list{
                           std::string("CONTRACT_MAIN_SETTLE_FEE_USER_IN"),
                           std::string("CONTRACT_MAIN_SETTLE_FEE_USER_OUT")},
                       false);
                 }
                 return this->parseFundingHistories(bills, market, since,
                                                    limit);
               })
        .share();
  }

  virtual std::any parseFundingHistory(std::any contract,
                                       std::any market = std::any{}) {
    //
    //     {
    //         "billId": "1111499428100472833",
    //         "symbol": "BTCUSDT",
    //         "amount": "-0.004992",
    //         "fee": "0",
    //         "feeByCoupon": "",
    //         "businessType": "contract_settle_fee",
    //         "coin": "USDT",
    //         "cTime": "1700728034996"
    //     }
    //
    //     {
    //         "category": "Margin",
    //         "id": "13111111111111111",
    //         "symbol": "BTCUSDT",
    //         "coin": "BTC",
    //         "type": "ORDER_DEALT_IN",
    //         "amount": "0.00531168",
    //         "fee": "-0.00000531",
    //         "balance": "55.10017801",
    //         "ts": "1745853486185"
    //     }
    //
    std::any marketId = this->safeString(contract, std::string("symbol"));
    std::any currencyId = this->safeString(contract, std::string("coin"));
    std::any timestamp =
        this->safeInteger2(contract, std::string("cTime"), std::string("ts"));
    return ccxt::dict{
        {std::string("info"), contract},
        {std::string("symbol"),
         this->safeSymbol(marketId, market, std::any{}, std::string("swap"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("code"), this->safeCurrencyCode(currencyId)},
        {std::string("amount"),
         this->safeNumber(contract, std::string("amount"))},
        {std::string("id"),
         this->safeString2(contract, std::string("billId"), std::string("id"))},
    };
  }

  virtual std::any parseFundingHistories(std::any contracts,
                                         std::any market = std::any{},
                                         std::any since = std::any{},
                                         std::any limit = std::any{}) {
    std::any result = ccxt::list{};
    for (std::any i = 0; isLessThan(i, getArrayLength(contracts));
         postFixIncrement(i)) {
      std::any contract = ::getValue(contracts, i);
      // for non-uta, we've set bussinessType in request payload. Not sure why
      // this existed. const business = this.safeString (contract,
      // 'businessType'); if (business !== 'contract_settle_fee') {
      //     continue;
      // }
      arrayPush(result, this->parseFundingHistory(contract, market));
    }
    std::any sorted = this->sortBy(result, std::string("timestamp"));
    std::any symbol = std::any{};
    if (isTrue(!isEqual(market, std::any{}))) {
      symbol = ::getValue(market, std::string("symbol"));
    }
    return this->filterBySymbolSinceLimit(sorted, symbol, since, limit);
  }

  virtual std::shared_future<std::any>
  modifyMarginHelper(std::any symbol, std::any amount, std::any type,
                     std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any holdSide =
                     this->safeString(params, std::string("holdSide"));
                 std::any market = this->market(symbol);
                 std::any productType = std::any{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("marginCoin"),
                      ::getValue(market, std::string("settleId"))},
                     {std::string("amount"),
                      this->amountToPrecision(symbol, amount)},
                     {std::string("holdSide"), holdSide},
                     {std::string("productType"), productType},
                 };
                 params = this->omit(params, std::string("holdSide"));
                 std::any response =
                     awaitValue(this->privateMixPostV2MixAccountSetMargin(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700813444618,
                 //         "data": ""
                 //     }
                 //
                 return this->extend(
                     this->parseMarginModification(response, market),
                     ccxt::dict{
                         {std::string("amount"), this->parseNumber(amount)},
                         {std::string("type"), type},
                     });
               })
        .share();
  }

  std::any parseMarginModification(std::any data,
                                   std::any market = std::any{}) override {
    //
    // addMargin/reduceMargin
    //
    //     {
    //         "code": "00000",
    //         "msg": "success",
    //         "requestTime": 1700813444618,
    //         "data": ""
    //     }
    //
    std::any errorCode = this->safeString(data, std::string("code"));
    std::any status = (isTrue((isEqual(errorCode, std::string("00000"))))
                           ? std::any(std::string("ok"))
                           : std::any(std::string("failed")));
    return ccxt::dict{
        {std::string("info"), data},
        {std::string("symbol"),
         this->safeString(market, std::string("symbol"))},
        {std::string("type"), std::any{}},
        {std::string("marginMode"), std::string("isolated")},
        {std::string("amount"), std::any{}},
        {std::string("total"), std::any{}},
        {std::string("code"), this->safeString(market, std::string("settle"))},
        {std::string("status"), status},
        {std::string("timestamp"), std::any{}},
        {std::string("datetime"), std::any{}},
    };
  }

  /**
   * @method
   * @name bitget#reduceMargin
   * @description remove margin from a position
   * @see https://www.bitget.com/api-doc/contract/account/Change-Margin
   * @param {string} symbol unified market symbol
   * @param {float} amount the amount of margin to remove
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [margin structure]{@link
   * https://docs.ccxt.com/?id=margin-structure}
   */
  std::shared_future<std::any>
  reduceMargin(std::any symbol, std::any amount,
               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isGreaterThan(amount, 0))) {
                   throw BadRequest(toString(add(
                       this->id, std::string(" reduceMargin() amount parameter "
                                             "must be a negative value"))));
                 }
                 std::any holdSide =
                     this->safeString(params, std::string("holdSide"));
                 if (isTrue(isEqual(holdSide, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" reduceMargin() requires a holdSide "
                                       "parameter, either long or short"))));
                 }
                 return awaitValue(this->modifyMarginHelper(
                     symbol, amount, std::string("reduce"), params));
               })
        .share();
  }

  /**
   * @method
   * @name bitget#addMargin
   * @description add margin
   * @see https://www.bitget.com/api-doc/contract/account/Change-Margin
   * @param {string} symbol unified market symbol
   * @param {float} amount the amount of margin to add
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [margin structure]{@link
   * https://docs.ccxt.com/?id=margin-structure}
   */
  std::shared_future<std::any>
  addMargin(std::any symbol, std::any amount,
            std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any holdSide =
                            this->safeString(params, std::string("holdSide"));
                        if (isTrue(isEqual(holdSide, std::any{}))) {
                          throw ArgumentsRequired(toString(add(
                              this->id,
                              std::string(" addMargin() requires a holdSide "
                                          "parameter, either long or short"))));
                        }
                        return awaitValue(this->modifyMarginHelper(
                            symbol, amount, std::string("add"), params));
                      })
        .share();
  }

  /**
   * @method
   * @name bitget#fetchLeverage
   * @description fetch the set leverage for a market
   * @see https://www.bitget.com/api-doc/contract/account/Get-Single-Account
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [leverage structure]{@link
   * https://docs.ccxt.com/?id=leverage-structure}
   */
  std::shared_future<std::any>
  fetchLeverage(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any productType = std::any{};
                        std::any productTypeparamsVariable =
                            this->handleProductTypeAndParams(market, params);
                        productType = ::getValue(productTypeparamsVariable, 0);
                        params = ::getValue(productTypeparamsVariable, 1);
                        std::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                            {std::string("marginCoin"),
                             ::getValue(market, std::string("settleId"))},
                            {std::string("productType"), productType},
                        };
                        std::any response =
                            awaitValue(this->privateMixGetV2MixAccountAccount(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "code": "00000",
                        //         "msg": "success",
                        //         "requestTime": 1709366911964,
                        //         "data": {
                        //             "marginCoin": "USDT",
                        //             "locked": "0",
                        //             "available": "0",
                        //             "crossedMaxAvailable": "0",
                        //             "isolatedMaxAvailable": "0",
                        //             "maxTransferOut": "0",
                        //             "accountEquity": "0",
                        //             "usdtEquity": "0.000000009166",
                        //             "btcEquity": "0",
                        //             "crossedRiskRate": "0",
                        //             "crossedMarginLeverage": 20,
                        //             "isolatedLongLever": 20,
                        //             "isolatedShortLever": 20,
                        //             "marginMode": "crossed",
                        //             "posMode": "hedge_mode",
                        //             "unrealizedPL": "0",
                        //             "coupon": "0",
                        //             "crossedUnrealizedPL": "0",
                        //             "isolatedUnrealizedPL": ""
                        //         }
                        //     }
                        //
                        std::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        return this->parseLeverage(data, market);
                      })
        .share();
  }

  std::any parseLeverage(std::any leverage,
                         std::any market = std::any{}) override {
    std::any isCrossMarginMode =
        isEqual(this->safeString(leverage, std::string("marginMode")),
                std::string("crossed"));
    std::any longLevKey = (isTrue(isCrossMarginMode)
                               ? std::any(std::string("crossedMarginLeverage"))
                               : std::any(std::string("isolatedLongLever")));
    std::any shortLevKey = (isTrue(isCrossMarginMode)
                                ? std::any(std::string("crossedMarginLeverage"))
                                : std::any(std::string("isolatedShortLever")));
    return ccxt::dict{
        {std::string("info"), leverage},
        {std::string("symbol"),
         this->safeString(market, std::string("symbol"))},
        {std::string("marginMode"),
         (isTrue(isCrossMarginMode) ? std::any(std::string("cross"))
                                    : std::any(std::string("isolated")))},
        {std::string("longLeverage"), this->safeInteger(leverage, longLevKey)},
        {std::string("shortLeverage"),
         this->safeInteger(leverage, shortLevKey)},
    };
  }

  /**
   * @method
   * @name bitget#setLeverage
   * @description set the level of leverage for a market
   * @see https://www.bitget.com/api-doc/contract/account/Change-Leverage
   * @see https://www.bitget.com/api-doc/uta/account/Change-Leverage
   * @param {int} leverage the rate of leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.holdSide] *isolated only* position direction,
   * 'long' or 'short'
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @param {boolean} [params.posSide] required for uta isolated margin, long or
   * short
   * @returns {object} response from the exchange
   */
  std::shared_future<std::any>
  setLeverage(std::any leverage, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " setLeverage() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any productType = std::any{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("leverage"), this->numberToString(leverage)},
                 };
                 std::any uta = std::any{};
                 std::any response = ccxt::dict{};
                 std::any utaparamsVariable =
                     awaitValue(this->handleUTAAndParams(
                         params, std::string("setLeverage"), false));
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(isEqual(uta, true))) {
                   if (isTrue(isEqual(productType, std::string("SPOT")))) {
                     std::any marginMode = std::any{};
                     std::any marginModeparamsVariable =
                         this->handleMarginModeAndParams(
                             std::string("setLeverage"), params);
                     marginMode = ::getValue(marginModeparamsVariable, 0);
                     params = ::getValue(marginModeparamsVariable, 1);
                     if (isTrue(!isEqual(marginMode, std::any{}))) {
                       productType = std::string("MARGIN");
                     }
                   }
                   ::setValue(request, std::string("coin"),
                              ::getValue(market, std::string("settleId")));
                   ::setValue(request, std::string("category"), productType);
                   response =
                       awaitValue(this->privateUtaPostV3AccountSetLeverage(
                           this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("marginCoin"),
                              ::getValue(market, std::string("settleId")));
                   ::setValue(request, std::string("productType"), productType);
                   response =
                       awaitValue(this->privateMixPostV2MixAccountSetLeverage(
                           this->extend(request, params)));
                 }
                 return response;
               })
        .share();
  }

  /**
   * @method
   * @name bitget#setMarginMode
   * @description set margin mode to 'cross' or 'isolated'
   * @see https://www.bitget.com/api-doc/contract/account/Change-Margin-Mode
   * @param {string} marginMode 'cross' or 'isolated'
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} response from the exchange
   */
  std::shared_future<std::any>
  setMarginMode(std::any marginMode, std::any symbol = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " setMarginMode() requires a symbol argument"))));
                 }
                 marginMode = toLowerCase(marginMode);
                 if (isTrue(isEqual(marginMode, std::string("cross")))) {
                   marginMode = std::string("crossed");
                 }
                 if (isTrue(isTrue((!isEqual(marginMode,
                                             std::string("isolated")))) &&
                            isTrue((!isEqual(marginMode,
                                             std::string("crossed")))))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" setMarginMode() marginMode must be "
                                       "either isolated or crossed (cross)"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any productType = std::any{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("marginCoin"),
                      ::getValue(market, std::string("settleId"))},
                     {std::string("marginMode"), marginMode},
                     {std::string("productType"), productType},
                 };
                 std::any response =
                     awaitValue(this->privateMixPostV2MixAccountSetMarginMode(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700865205552,
                 //         "data": {
                 //             "symbol": "BTCUSDT",
                 //             "marginCoin": "USDT",
                 //             "longLeverage": "20",
                 //             "shortLeverage": "3",
                 //             "marginMode": "isolated"
                 //         }
                 //     }
                 //
                 return response;
               })
        .share();
  }

  /**
   * @method
   * @name bitget#setPositionMode
   * @description set hedged to true or false for a market
   * @see https://www.bitget.com/api-doc/contract/account/Change-Hold-Mode
   * @see https://www.bitget.com/api-doc/uta/account/Change-Position-Mode
   * @param {bool} hedged set to true to use dualSidePosition
   * @param {string} symbol not used by setPositionMode ()
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.productType] required if not uta and symbol is
   * undefined: 'USDT-FUTURES', 'USDC-FUTURES', 'COIN-FUTURES', 'SUSDT-FUTURES',
   * 'SUSDC-FUTURES' or 'SCOIN-FUTURES'
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object} response from the exchange
   */
  std::shared_future<std::any>
  setPositionMode(std::any hedged, std::any symbol = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any posMode =
                     (isTrue(hedged) ? std::any(std::string("hedge_mode"))
                                     : std::any(std::string("one_way_mode")));
                 std::any request = ccxt::dict{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any productType = std::any{};
                 std::any uta = std::any{};
                 std::any response = ccxt::dict{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any utaparamsVariable =
                     awaitValue(this->handleUTAAndParams(
                         params, std::string("setPositionMode"), false));
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(isEqual(uta, true))) {
                   ::setValue(request, std::string("holdMode"), posMode);
                   response =
                       awaitValue(this->privateUtaPostV3AccountSetHoldMode(
                           this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("posMode"), posMode);
                   ::setValue(request, std::string("productType"), productType);
                   response = awaitValue(
                       this->privateMixPostV2MixAccountSetPositionMode(
                           this->extend(request, params)));
                 }
                 return response;
               })
        .share();
  }

  /**
   * @method
   * @name bitget#fetchOpenInterest
   * @description retrieves the open interest of a contract trading pair
   * @see https://www.bitget.com/api-doc/contract/market/Get-Open-Interest
   * @see https://www.bitget.com/api-doc/uta/public/Get-Open-Interest
   * @param {string} symbol unified CCXT market symbol
   * @param {object} [params] exchange specific parameters
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object} an open interest structure{@link
   * https://docs.ccxt.com/?id=open-interest-structure}
   */
  std::shared_future<std::any>
  fetchOpenInterest(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(!isEqual(
                         ::getValue(market, std::string("contract")), true))) {
                   throw BadRequest(toString(add(
                       this->id, std::string(" fetchOpenInterest() supports "
                                             "contract markets only"))));
                 }
                 std::any productType = std::any{};
                 std::any productTypeparamsVariable =
                     this->handleProductTypeAndParams(market, params);
                 productType = ::getValue(productTypeparamsVariable, 0);
                 params = ::getValue(productTypeparamsVariable, 1);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any uta = std::any{};
                 std::any response = std::any{};
                 std::any utaparamsVariable =
                     awaitValue(this->handleUTAAndParams(
                         params, std::string("fetchOpenInterest"), false));
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(isEqual(uta, true))) {
                   ::setValue(request, std::string("category"), productType);
                   response = awaitValue(this->publicUtaGetV3MarketOpenInterest(
                       this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("productType"), productType);
                   response =
                       awaitValue(this->publicMixGetV2MixMarketOpenInterest(
                           this->extend(request, params)));
                 }
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 return this->parseOpenInterest(data, market);
               })
        .share();
  }

  std::any parseOpenInterest(std::any interest,
                             std::any market = std::any{}) override {
    //
    // default
    //
    //     {
    //         "openInterestList": [
    //             {
    //                 "symbol": "BTCUSDT",
    //                 "size": "52234.134"
    //             }
    //         ],
    //         "ts": "1700866041023"
    //     }
    //
    // uta
    //
    //     {
    //         "list": [
    //             {
    //                 "symbol": "BTCUSDT",
    //                 "openInterest": "18166.3583"
    //             }
    //         ],
    //         "ts": "1751101220993"
    //     }
    //
    std::any data = this->safeList2(interest, std::string("openInterestList"),
                                    std::string("list"), ccxt::list{});
    std::any timestamp = this->safeInteger(interest, std::string("ts"));
    std::any marketId =
        this->safeString(::getValue(data, 0), std::string("symbol"));
    return this->safeOpenInterest(
        ccxt::dict{
            {std::string("symbol"),
             this->safeSymbol(marketId, market, std::any{},
                              std::string("contract"))},
            {std::string("openInterestAmount"),
             this->safeNumber2(::getValue(data, 0), std::string("size"),
                               std::string("openInterest"))},
            {std::string("openInterestValue"), std::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("info"), interest},
        },
        market);
  }

  /**
   * @method
   * @name bitget#fetchTransfers
   * @description fetch a history of internal transfers made on an account
   * @see
   * https://www.bitget.com/api-doc/spot/account/Get-Account-TransferRecords
   * @param {string} code unified currency code of the currency transferred
   * @param {int} [since] the earliest time in ms to fetch transfers for
   * @param {int} [limit] the maximum number of transfers structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch entries for
   * @returns {object[]} a list of [transfer structures]{@link
   * https://docs.ccxt.com/?id=transfer-structure}
   */
  std::shared_future<std::any>
  fetchTransfers(std::any code = std::any{}, std::any since = std::any{},
                 std::any limit = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(code, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchTransfers() requires a code argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any type = std::any{};
                 std::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchTransfers"), std::any{}, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 std::any fromAccount =
                     this->safeString(params, std::string("fromAccount"), type);
                 params = this->omit(params, std::string("fromAccount"));
                 std::any accountsByType = this->safeValue(
                     this->options, std::string("accountsByType"),
                     ccxt::dict{});
                 type = this->safeString(accountsByType, fromAccount);
                 std::any currency = this->currency(code);
                 std::any request = ccxt::dict{
                     {std::string("coin"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("fromType"), type},
                 };
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any requestparamsVariable = this->handleUntilOption(
                     std::string("endTime"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 std::any response = awaitValue(
                     this->privateSpotGetV2SpotAccountTransferRecords(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700873854651,
                 //         "data": [
                 //             {
                 //                 "coin": "USDT",
                 //                 "status": "Successful",
                 //                 "toType": "crossed_margin",
                 //                 "toSymbol": "",
                 //                 "fromType": "spot",
                 //                 "fromSymbol": "",
                 //                 "size": "11.64958799",
                 //                 "ts": "1700729673028",
                 //                 "clientOid": "1111506298504744960",
                 //                 "transferId": "24930940"
                 //             },
                 //         ]
                 //     }
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseTransfers(data, currency, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name bitget#transfer
   * @description transfer currency internally between wallets on the same
   * account
   * @see https://www.bitget.com/api-doc/spot/account/Wallet-Transfer
   * @see https://www.bitget.com/api-doc/uta/account/transfer
   * @param {string} code unified currency code
   * @param {float} amount amount to transfer
   * @param {string} fromAccount account to transfer from
   * @param {string} toAccount account to transfer to
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true to transfer via the unified
   * trading account v3 endpoint
   * @param {string} [params.symbol] unified CCXT market symbol, required when
   * transferring to or from an account type that is a leveraged
   * position-by-position account
   * @param {string} [params.clientOid] custom id
   * @returns {object} a [transfer structure]{@link
   * https://docs.ccxt.com/?id=transfer-structure}
   */
  std::shared_future<std::any>
  transfer(std::any code, std::any amount, std::any fromAccount,
           std::any toAccount, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any uta = std::any{};
                 std::any utaparamsVariable =
                     awaitValue(this->handleUTAAndParams(
                         params, std::string("transfer"), false));
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any currency = this->currency(code);
                 std::any accountsByType = this->safeValue(
                     this->options, std::string("accountsByType"),
                     ccxt::dict{});
                 std::any fromType =
                     this->safeString(accountsByType, fromAccount);
                 std::any toType = this->safeString(accountsByType, toAccount);
                 std::any request = ccxt::dict{
                     {std::string("fromType"), fromType},
                     {std::string("toType"), toType},
                     {std::string("amount"), amount},
                     {std::string("coin"),
                      ::getValue(currency, std::string("id"))},
                 };
                 std::any symbol =
                     this->safeString(params, std::string("symbol"));
                 params = this->omit(params, std::string("symbol"));
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(uta, true))) {
                   response = awaitValue(this->privateUtaPostV3AccountTransfer(
                       this->extend(request, params)));
                 } else {
                   response =
                       awaitValue(this->privateSpotPostV2SpotWalletTransfer(
                           this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700874302021,
                 //         "data": {
                 //             "transferId": "1112112916581847040",
                 //             "clientOrderId": null
                 //         }
                 //     }
                 //
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::dict{});
                 ::setValue(
                     data, std::string("ts"),
                     this->safeInteger(response, std::string("requestTime")));
                 return this->parseTransfer(data, currency);
               })
        .share();
  }

  std::any parseTransfer(std::any transfer,
                         std::any currency = std::any{}) override {
    //
    // transfer
    //
    //     {
    //         "transferId": "1112112916581847040",
    //         "clientOrderId": null,
    //         "ts": 1700874302021
    //     }
    //
    // fetchTransfers
    //
    //     {
    //         "coin": "USDT",
    //         "status": "Successful",
    //         "toType": "crossed_margin",
    //         "toSymbol": "",
    //         "fromType": "spot",
    //         "fromSymbol": "",
    //         "size": "11.64958799",
    //         "ts": "1700729673028",
    //         "clientOid": "1111506298504744960",
    //         "transferId": "24930940"
    //     }
    //
    std::any timestamp = this->safeInteger(transfer, std::string("ts"));
    std::any status = this->safeStringLower(transfer, std::string("status"));
    std::any currencyId = this->safeString(transfer, std::string("coin"));
    std::any fromAccountRaw =
        this->safeString(transfer, std::string("fromType"));
    std::any accountsById = this->safeValue(
        this->options, std::string("accountsById"), ccxt::dict{});
    std::any fromAccount =
        this->safeString(accountsById, fromAccountRaw, fromAccountRaw);
    std::any toAccountRaw = this->safeString(transfer, std::string("toType"));
    std::any toAccount =
        this->safeString(accountsById, toAccountRaw, toAccountRaw);
    return ccxt::dict{
        {std::string("info"), transfer},
        {std::string("id"),
         this->safeString(transfer, std::string("transferId"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("currency"), this->safeCurrencyCode(currencyId, currency)},
        {std::string("amount"),
         this->safeNumber(transfer, std::string("size"))},
        {std::string("fromAccount"), fromAccount},
        {std::string("toAccount"), toAccount},
        {std::string("status"), this->parseTransferStatus(status)},
    };
  }

  virtual std::any parseTransferStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("successful"), std::string("ok")},
    };
    return this->safeString(statuses, status, status);
  }

  std::any parseDepositWithdrawFee(std::any fee,
                                   std::any currency = std::any{}) override {
    //
    //     {
    //         "chains": [
    //             {
    //                 "browserUrl":
    //                 "https://blockchair.com/bitcoin/transaction/", "chain":
    //                 "BTC", "depositConfirm": "1", "extraWithdrawFee": "0",
    //                 "minDepositAmount": "0.0001",
    //                 "minWithdrawAmount": "0.005",
    //                 "needTag": "false",
    //                 "rechargeable": "true",
    //                 "withdrawConfirm": "1",
    //                 "withdrawFee": "0.0004",
    //                 "withdrawable": "true"
    //             },
    //         ],
    //         "coin": "BTC",
    //         "coinId": "1",
    //         "transfer": "true""
    //     }
    //
    std::any chains = this->safeValue(fee, std::string("chains"), ccxt::list{});
    std::any chainsLength = getArrayLength(chains);
    std::any result = ccxt::dict{
        {std::string("info"), fee},
        {std::string("withdraw"),
         ccxt::dict{
             {std::string("fee"), std::any{}},
             {std::string("percentage"), std::any{}},
         }},
        {std::string("deposit"),
         ccxt::dict{
             {std::string("fee"), std::any{}},
             {std::string("percentage"), std::any{}},
         }},
        {std::string("networks"), ccxt::dict{}},
    };
    for (std::any i = 0; isLessThan(i, chainsLength); postFixIncrement(i)) {
      std::any chain = ::getValue(chains, i);
      std::any networkId = this->safeString(chain, std::string("chain"));
      std::any currencyCode = this->safeString(currency, std::string("code"));
      std::any networkCode = this->networkIdToCode(networkId, currencyCode);
      if (isTrue(!isEqual(networkCode, std::any{}))) {
        ::setValue(
            ::getValue(result, std::string("networks")), networkCode,
            ccxt::dict{
                {std::string("deposit"),
                 ccxt::dict{
                     {std::string("fee"), std::any{}},
                     {std::string("percentage"), std::any{}},
                 }},
                {std::string("withdraw"),
                 ccxt::dict{
                     {std::string("fee"),
                      this->safeNumber(chain, std::string("withdrawFee"))},
                     {std::string("percentage"), false},
                 }},
            });
      }
      if (isTrue(isEqual(chainsLength, 1))) {
        ::setValue(::getValue(result, std::string("withdraw")),
                   std::string("fee"),
                   this->safeNumber(chain, std::string("withdrawFee")));
        ::setValue(::getValue(result, std::string("withdraw")),
                   std::string("percentage"), false);
      }
    }
    return result;
  }

  /**
   * @method
   * @name bitget#fetchDepositWithdrawFees
   * @description fetch deposit and withdraw fees
   * @see https://www.bitget.com/api-doc/spot/market/Get-Coin-List
   * @param {string[]|undefined} codes list of unified currency codes
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a list of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<std::any>
  fetchDepositWithdrawFees(std::any codes = std::any{},
                           std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any response = awaitValue(
                            this->publicSpotGetV2SpotPublicCoins(params));
                        //
                        //     {
                        //         "code": "00000",
                        //         "data": [
                        //             {
                        //                 "chains": [
                        //                     {
                        //                         "browserUrl":
                        //                         "https://blockchair.com/bitcoin/transaction/",
                        //                         "chain": "BTC",
                        //                         "depositConfirm": "1",
                        //                         "extraWithdrawFee": "0",
                        //                         "minDepositAmount": "0.0001",
                        //                         "minWithdrawAmount": "0.005",
                        //                         "needTag": "false",
                        //                         "rechargeable": "true",
                        //                         "withdrawConfirm": "1",
                        //                         "withdrawFee": "0.0004",
                        //                         "withdrawable": "true"
                        //                     },
                        //                 ],
                        //                 "coin": "BTC",
                        //                 "coinId": "1",
                        //                 "transfer": "true""
                        //             }
                        //         ],
                        //         "msg": "success",
                        //         "requestTime": "1700120731773"
                        //     }
                        //
                        std::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseDepositWithdrawFees(
                            data, codes, std::string("coin"));
                      })
        .share();
  }

  /**
   * @method
   * @name bitget#borrowCrossMargin
   * @description create a loan to borrow margin
   * @see https://www.bitget.com/api-doc/margin/cross/account/Cross-Borrow
   * @param {string} code unified currency code of the currency to borrow
   * @param {string} amount the amount to borrow
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [margin loan structure]{@link
   * https://docs.ccxt.com/?id=margin-loan-structure}
   */
  std::shared_future<std::any>
  borrowCrossMargin(std::any code, std::any amount,
                    std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = this->currency(code);
                        std::any request = ccxt::dict{
                            {std::string("coin"),
                             ::getValue(currency, std::string("id"))},
                            {std::string("borrowAmount"),
                             this->currencyToPrecision(code, amount)},
                        };
                        std::any response = awaitValue(
                            this->privateMarginPostV2MarginCrossedAccountBorrow(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "code": "00000",
                        //         "msg": "success",
                        //         "requestTime": 1700876470931,
                        //         "data": {
                        //             "loanId": "1112122013642272769",
                        //             "coin": "USDT",
                        //             "borrowAmount": "4"
                        //         }
                        //     }
                        //
                        std::any data = this->safeValue(
                            response, std::string("data"), ccxt::dict{});
                        return this->parseMarginLoan(data, currency);
                      })
        .share();
  }

  /**
   * @method
   * @name bitget#borrowIsolatedMargin
   * @description create a loan to borrow margin
   * @see https://www.bitget.com/api-doc/margin/isolated/account/Isolated-Borrow
   * @param {string} symbol unified market symbol
   * @param {string} code unified currency code of the currency to borrow
   * @param {string} amount the amount to borrow
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [margin loan structure]{@link
   * https://docs.ccxt.com/?id=margin-loan-structure}
   */
  std::shared_future<std::any>
  borrowIsolatedMargin(std::any symbol, std::any code, std::any amount,
                       std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency = this->currency(code);
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("coin"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("borrowAmount"),
                      this->currencyToPrecision(code, amount)},
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response = awaitValue(
                     this->privateMarginPostV2MarginIsolatedAccountBorrow(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": "00000",
                 //         "msg": "success",
                 //         "requestTime": 1700877255605,
                 //         "data": {
                 //             "loanId": "1112125304879067137",
                 //             "symbol": "BTCUSDT",
                 //             "coin": "USDT",
                 //             "borrowAmount": "4"
                 //         }
                 //     }
                 //
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::dict{});
                 return this->parseMarginLoan(data, currency, market);
               })
        .share();
  }

  /**
   * @method
   * @name bitget#repayIsolatedMargin
   * @description repay borrowed margin and interest
   * @see https://www.bitget.com/api-doc/margin/isolated/account/Isolated-Repay
   * @param {string} symbol unified market symbol
   * @param {string} code unified currency code of the currency to repay
   * @param {string} amount the amount to repay
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [margin loan structure]{@link
   * https://docs.ccxt.com/?id=margin-loan-structure}
   */
  std::shared_future<std::any>
  repayIsolatedMargin(std::any symbol, std::any code, std::any amount,
                      std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = this->currency(code);
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("coin"),
                             ::getValue(currency, std::string("id"))},
                            {std::string("repayAmount"),
                             this->currencyToPrecision(code, amount)},
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        std::any response = awaitValue(
                            this->privateMarginPostV2MarginIsolatedAccountRepay(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "code": "00000",
                        //         "msg": "success",
                        //         "requestTime": 1700877518012,
                        //         "data": {
                        //             "remainDebtAmount": "0",
                        //             "repayId": "1112126405439270912",
                        //             "symbol": "BTCUSDT",
                        //             "coin": "USDT",
                        //             "repayAmount": "8.000137"
                        //         }
                        //     }
                        //
                        std::any data = this->safeValue(
                            response, std::string("data"), ccxt::dict{});
                        return this->parseMarginLoan(data, currency, market);
                      })
        .share();
  }

